class Solution {
public:
    string convertToTitle(int num) {
        string ans="";
        while(num)
        {
            num-=1;
            int rem=(num%26);
            char ch='A'+rem;
            ans+=ch;
            num/=26;
        }
        reverse(ans.begin(),ans.end());
        return ans;
    }
};

class Solution:
    # @param {integer} n
    # @return {string}
    def convertToTitle(self, n):
        s = ""

        while True:
            m = n/26
            k = n%26
            if k == 0:
                k = 26
                m = m - 1
            s = s + chr(ord('A')+k-1)
            if m==0:
                break
            n = m
        return s[::-1]


